"""Retry wrapper migrated from Meridian CRM 4.2 integration semantics."""

from typing import Any, Callable


class TransientError(Exception):
    """A retryable transport failure, such as a timeout or server error."""


class PermanentError(Exception):
    """A non-retryable transport failure, such as a client or auth error."""


def call_with_retry(endpoint_cfg: dict, transport: Callable[[str, int], Any]) -> dict:
    """Call an injected transport using the configured retry-count convention.

    ``retry`` specifies the number of re-attempts after the initial attempt.
    """
    url = endpoint_cfg["url"]
    timeout_ms = endpoint_cfg["timeout_ms"]
    max_attempts = endpoint_cfg["retry"] + 1

    for attempts in range(1, max_attempts + 1):
        try:
            result = transport(url, timeout_ms)
            return {
                "ok": True,
                "attempts": attempts,
                "result": result,
                "error": None,
            }
        except PermanentError as error:
            return {
                "ok": False,
                "attempts": attempts,
                "result": None,
                "error": {
                    "type": "permanent",
                    "message": str(error),
                },
            }
        except TransientError as error:
            if attempts == max_attempts:
                return {
                    "ok": False,
                    "attempts": attempts,
                    "result": None,
                    "error": {
                        "type": "transient",
                        "message": str(error),
                    },
                }

    raise RuntimeError("unreachable")
